const input = $json;

// Helper function to remove duplicate sentences/paragraphs from repetitive AI outputs
function deduplicateSentences(text) {
  if (!text || typeof text !== "string") return "";

  // Split into sentences using period, exclamation, or question marks followed by a space
  const sentences = text.split(/(?<=[.!?])\s+/);

  // Keep only unique, non-empty sentences
  const uniqueSentences = [];
  for (const sentence of sentences) {
    const trimmed = sentence.trim();
    if (trimmed && !uniqueSentences.includes(trimmed)) {
      uniqueSentences.push(trimmed);
    }
  }

  return uniqueSentences.join(" ");
}

// Extract the actual text returned by the AI model
let text =
  input.output?.[0]?.content?.[0]?.text ||
  input.output_text ||
  input.text ||
  input.message ||
  input.content ||
  "";

// If no valid text was found, return the original item with an error flag
if (typeof text !== "string" || !text.trim()) {
  return [
    {
      json: {
        ...$("Processing the leads one by one").item.json,
        parsing_error: true,
        parsing_error_message: "No valid AI text response found",
        raw_ai_response: input
      }
    }
  ];
}

// Clean markdown code fences if the AI returned JSON inside ```json
text = text
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

try {
  const parsed = JSON.parse(text);

  return [
    {
      json: {
        ...$("Processing the leads one by one").item.json,

        qualified: parsed.qualified ?? false,
        score: parsed.score ?? parsed.lead_score ?? parsed.Lead_Score ?? 70,
        pain_point: parsed.pain_point ?? "",
        ai_opportunity: parsed.ai_opportunity ?? "",
        qualification_reason:
          parsed.reason ??
          parsed.qualification_reason ??
          "",

        // Map and clean outreach messages to remove any duplicated text
        Connection_Message: deduplicateSentences(parsed.connection_message ?? parsed.Connection_Message),
        Followup_1: deduplicateSentences(parsed.followup_1 ?? parsed.Followup_1),
        Followup_2: deduplicateSentences(parsed.followup_2 ?? parsed.Followup_2),
        Followup_3: deduplicateSentences(parsed.followup_3 ?? parsed.Followup_3)
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        ...$("Processing the leads one by one").item.json,

        parsing_error: true,
        parsing_error_message: error.message,
        raw_ai_response: text
      }
    }
  ];
}

const input = $json;

// Extract AI response text
let text = input.output?.[0]?.content?.[0]?.text || input.output_text || input.text || input.message || input.content || "";

// Validate response
if (typeof text !== "string" || !text.trim()) {
  return [{
    json: {
      ...input,
      parsing_error: true,
      parsing_error_message: "No valid AI text response found",
      raw_response: input
    }
  }];
}

// Clean markdown formatting
text = text.replace(/```json/gi, "").replace(/```/g, "").trim();

try {
  const parsed = JSON.parse(text);

  // Safely grab score from previous node if not in current AI response
  const previousScore = $('Organize lead Analysis').item.json.score ?? $('Organize lead Analysis').item.json.lead_score;

  return [{
    json: {
      ...input,
      connection_message: parsed.connection_message ?? "",
      followup_1: parsed.followup_1 ?? "",
      followup_2: parsed.followup_2 ?? "",
      followup_3: parsed.followup_3 ?? "",
      lead_score: parsed.lead_score ?? parsed.score ?? previousScore ?? 70
    }
  }];
} catch (error) {
  return [{
    json: {
      ...input,
      parsing_error: true,
      parsing_error_message: "Failed to parse JSON response",
      raw_response: text
    }
  }];
}
